cat > /tmp/claude-0/-home-user-TLDR/8fd1105f-43f1-53d8-be49-4ce6f13e3214/scratchpad/digest.py <<'EOF'
import json,sys,os,re
def brief(s,n): 
    s=re.sub(r'\s+',' ',str(s)); return s[:n]+('…' if len(s)>n else '')
for path in sys.argv[1:]:
    out=[]
    prev=None
    for line in open(path):
        line=line.strip()
        if not line: continue
        try: e=json.loads(line)
        except: continue
        ts=e.get('timestamp','')
        m=e.get('message',{}) or {}
        role=m.get('role') or e.get('type')
        c=m.get('content')
        items = c if isinstance(c,list) else [{'type':'text','text':c}] if c else []
        for it in items:
            if not isinstance(it,dict): continue
            t=it.get('type')
            if t=='text':
                txt=it.get('text','')
                if role=='user': out.append(f"[{ts}] USER: {brief(txt,3000)}")
                else: out.append(f"[{ts}] ASST: {brief(txt,1200)}")
            elif t=='thinking':
                out.append(f"[{ts}] think: {brief(it.get('thinking',''),400)}")
            elif t=='tool_use':
                out.append(f"[{ts}] TOOL {it.get('name')}: {brief(json.dumps(it.get('input',{}))[:600],600)}")
            elif t=='tool_result':
                cc=it.get('content')
                if isinstance(cc,list): cc=' '.join(x.get('text','') for x in cc if isinstance(x,dict))
                err=' ERR' if it.get('is_error') else ''
                out.append(f"[{ts}] res{err}: {brief(cc,300)}")
    open(path+'.digest.txt','w').write('\n'.join(out))
    print(path, len(out), os.path.getsize(path+'.digest.txt'))
EOF
cd /tmp/claude-0/-home-user-TLDR/8fd1105f-43f1-53d8-be49-4ce6f13e3214/scratchpad && python3 digest.py logs/*.jsonl

